input.new_string:
  node - "${ENV_FILE}" > "${payload_file}" <<'JS'
const crypto = require('crypto');
const fs = require('fs');

const path = process.argv[2];
const rawContents = fs.readFileSync(path);
const text = rawContents.toString('utf8');
const variables = {};

for (const rawLine of text.split(/\n/)) {
  let line = rawLine.replace(/\r$/, '');
  const stripped = line.trim();

  if (!stripped || stripped.startsWith('#')) continue;

  if (line.startsWith('export ')) {
    line = line.slice('export '.length);
  }

  if (!line.includes('=')) continue;

  const separatorIndex = line.indexOf('=');
  const key = line.slice(0, separatorIndex).trim();
  const value = line.slice(separatorIndex + 1);

  if (!key) continue;

  // Do not transmit raw secret values. The hash and length allow the
  // orchestrator to audit exactly which validated value was used without
  // exposing credentials in transit, logs, or downstream storage.
  variables[key] = {
    present: value.length > 0,
    value_length: value.length,
    value_sha256: crypto.createHash('sha256').update(value, 'utf8').digest('hex'),
  };
}

process.stdout.write(JSON.stringify({
  environment_file: path,
  raw_contents_sha256: crypto.createHash('sha256').update(rawContents).digest('hex'),
  variables,
}));
JS

