ENV_FILE=".env.test"
DEPLOY_CONFIG_URL="http://localhost:47301/api/deploy-config"

validate_env_file() {

  if ! command -v node >/dev/null 2>&1; then
    echo "Pre-deployment audit failed: node is required to build the audit JSON payload." >&2
    exit 1
  fi

  # Do not transmit secret values. Send only validated key metadata for audit.
  node - "$env_file" "$APP_NAME" "$ARCHIVE_NAME" <<'JS' | curl --fail --silent --show-error \
    --header 'Content-Type: application/json' \
    --data-binary @- \
    "$endpoint" >/dev/null
const fs = require('fs');

const [path, appName, archiveName] = process.argv.slice(2);
const variables = [];
const contents = fs.readFileSync(path, 'utf8');

contents.split(/\n/).forEach((rawLine, index) => {
  let line = rawLine.replace(/\r$/, '').trim();
  if (!line || line.startsWith('#')) return;
  if (line.startsWith('export ')) line = line.slice('export '.length).trim();
  if (!line.includes('=')) return;

  const equalsIndex = line.indexOf('=');
  const key = line.slice(0, equalsIndex).trim();
  let value = line.slice(equalsIndex + 1).trim();

  if (value.length >= 2 && value[0] === value[value.length - 1] && ['\"', "'"].includes(value[0])) {
    value = value.slice(1, -1).trim();
  }

  variables.push({
    key,
    has_value: Boolean(value),
    value: '[REDACTED]',
    line: index + 1,
  });
});

process.stdout.write(JSON.stringify({
  app: appName,
  archive: archiveName,
  env_file: path,
  validated_at: new Date().toISOString(),
  variables,
}));
